SELECT id,campaign_id,user_id,coupon_instance_id,claim_no,claimed_at,request_id
FROM coupon_claim
WHERE campaign_id=#{campaignId}
ORDER BY claimed_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT id,campaign_id,user_id,coupon_instance_id,claim_no,claimed_at,request_id
FROM coupon_claim
WHERE request_id=#{requestId}

mapper.update:
UPDATE coupon_template
SET status='ACTIVE', version=version+1, updated_at=#{now}
WHERE id=#{id} AND status='DRAFT' AND owner_type='MERCHANT' AND version=#{expectedVersion}

UPDATE coupon_campaign
SET name=#{name}, per_user_limit=#{perUserLimit}, total_limit=#{totalLimit},
    budget_limit=#{budgetLimit}, start_at=#{startAt}, end_at=#{endAt},
    description=#{description}, version=version+1, updated_at=#{now}
WHERE id=#{campaignId} AND owner_type='MERCHANT'
  AND status IN ('DRAFT','REJECTED') AND version=#{expectedVersion}

UPDATE coupon_campaign
SET status='PENDING_REVIEW', reject_reason=NULL, submitted_at=#{now},
    version=version+1, updated_at=#{now}
WHERE id=#{campaignId} AND owner_type='MERCHANT'
  AND status IN ('DRAFT','REJECTED') AND version=#{expectedVersion}

UPDATE coupon_campaign
SET status='CANCELED', version=version+1, updated_at=#{now}
WHERE id=#{campaignId} AND owner_type='MERCHANT'
  AND status IN ('DRAFT','REJECTED','PENDING_REVIEW') AND version=#{expectedVersion}

UPDATE coupon_campaign
SET status=#{toStatus}, reject_reason=#{rejectReason}, reviewed_at=#{now},
    reviewed_by_type=#{reviewerType}, reviewed_by_id=#{reviewerId},
    version=version+1, updated_at=#{now}
WHERE id=#{campaignId} AND owner_type='MERCHANT' AND status='PENDING_REVIEW'
  AND version=#{expectedVersion}

UPDATE coupon_campaign
SET status='PAUSED', version=version+1, updated_at=#{now}
WHERE id=#{campaignId} AND owner_type='MERCHANT'
  AND status IN ('SCHEDULED','ACTIVE') AND version=#{expectedVersion}

UPDATE coupon_campaign
SET status='ENDED', version=version+1, updated_at=#{now}
WHERE id=#{campaignId} AND owner_type='MERCHANT'
  AND status IN ('SCHEDULED','ACTIVE','PAUSED') AND version=#{expectedVersion}

